1	package routing
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/easel/fizeau/internal/reasoning"
8	)
9	
10	// Capabilities describes what a (harness, provider, model) tuple can do.
11	// Populated from harness config + catalog metadata + provider discovery.
12	type Capabilities struct {
13		ContextWindow      int      // resolved tokens; 0 = unknown
14		SupportsTools      bool     // supports tool/function calling
15		SupportsStreaming  bool     // supports streaming responses
16		SupportedReasoning []string // supported public reasoning values
17		MaxReasoningTokens int      // 0 means numeric reasoning is unsupported/unknown
18		SupportedPerms     []string // {"safe","supervised","unrestricted"} subset
19		ExactPinSupport    bool     // accepts exact concrete model pins
20		SupportedModels    []string // nil = no static allow-list
21	}
22	
23	// HasReasoning returns true if the candidate supports the requested reasoning
24	// value. Empty, auto, off, and numeric 0 impose no requirement.
25	func (c Capabilities) HasReasoning(value string) bool {
26		policy, err := reasoning.ParseString(value)
27		if err != nil {
28			return false
29		}
30		switch policy.Kind {
31		case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
32			return true
33		case reasoning.KindTokens:
34			return c.MaxReasoningTokens > 0 && policy.Tokens <= c.MaxReasoningTokens
35		case reasoning.KindNamed:
36			for _, supported := range c.SupportedReasoning {
37				normalized, err := reasoning.Normalize(supported)
38				if err == nil && normalized == policy.Value {
39					return true
40				}
41			}
42			return false
43		default:
44			return false
45		}
46	}
47	
48	// HasPermissions returns true if the candidate supports the requested level.
49	// An empty permission level always returns true.
50	func (c Capabilities) HasPermissions(perm string) bool {
51		if perm == "" {
52			return true
53		}
54		for _, p := range c.SupportedPerms {
55			if strings.EqualFold(p, perm) {
56				return true
57			}
58		}
59		return false
60	}
61	
62	// HasModel returns true when the exact model pin is within the static
63	// harness allow-list. A nil allow-list means the harness delegates validation
64	// to provider-side model checks.
65	func (c Capabilities) HasModel(model string) bool {
66		if c.SupportedModels == nil || model == "" {
67			return true
68		}
69		for _, supported := range c.SupportedModels {
70			if supported == model {
71				return true
72			}
73		}
74		return false
75	}
76	
77	// CheckGating applies all capability gates against a request and returns
78	// the first failure reason (free-form string for diagnostics) plus the
79	// typed FilterReason category for the failure. Returns ("", FilterReasonEligible)
80	// when all gates pass.
81	//
82	// The typed return is the authoritative classification — callers must not
83	// re-classify by parsing the string. The string is for human-readable
84	// diagnostics only.
85	//
86	// Fixes ddx-4817edfd subtree: pre-dispatch capability check covering
87	// context window, tool support, effort, permissions.
88	func CheckGating(cap Capabilities, req Request) (string, FilterReason) {
89		// Context window gating: if the request declares prompt size or an effort
90		// that implies a minimum context, reject candidates that can't fit.
91		minCtx := req.MinContextWindow()
92		if minCtx > 0 {
93			if cap.ContextWindow <= 0 {
94				return fmt.Sprintf("context window unknown < required %d", minCtx), FilterReasonContextTooSmall
95			}
96			if cap.ContextWindow < minCtx {
97				return fmt.Sprintf("context window %d < required %d", cap.ContextWindow, minCtx), FilterReasonContextTooSmall
98			}
99		}
100	
101		// Tool-calling support gating.
102		if req.RequiresTools && !cap.SupportsTools {
103			return "tool calling not supported", FilterReasonNoToolSupport
104		}
105	
106		if !cap.HasReasoning(req.Reasoning) {
107			return fmt.Sprintf("reasoning %q not supported", req.Reasoning), FilterReasonReasoningUnsupported
108		}
109	
110		// Permissions support gating.
111		if !cap.HasPermissions(req.Permissions) {
112			return fmt.Sprintf("permissions %q not supported", req.Permissions), FilterReasonScoredBelowTop
113		}
114	
115		if req.Model != "" && !cap.HasModel(req.Model) {
116			return "model not in harness allow-list", FilterReasonScoredBelowTop
117		}
118	
119		// Exact-pin gating: an explicit Model field requires ExactPinSupport.
120		if req.Model != "" && !cap.ExactPinSupport {
121			return "exact model pin not supported", FilterReasonScoredBelowTop
122		}
123	
124		return "", FilterReasonEligible
125	}
126	
127	// CheckPowerEligibility applies catalog-power gates for unpinned automatic
128	// routing. Any explicit hard route pin (harness, provider, or model) bypasses
129	// this gate so caller-chosen routes are never broadened or overridden by
130	// power policy.
131	func CheckPowerEligibility(lookup func(string) (ModelEligibility, bool), model string, req Request) (string, FilterReason) {
132		if req.Model != "" || req.Provider != "" || req.Harness != "" || lookup == nil {
133			return "", FilterReasonEligible
134		}
135		if model == "" {
136			return "model has no catalog power metadata", FilterReasonPowerMissing
137		}
138		eligibility, ok := lookup(model)
139		if !ok {
140			if req.MinPower > 0 || req.MaxPower > 0 {
141				return fmt.Sprintf("model %q has no catalog power metadata", model), FilterReasonPowerMissing
142			}
143			return "", FilterReasonEligible
144		}
145		if eligibility.ExactPinOnly {
146			return fmt.Sprintf("model %q is exact-pin-only", model), FilterReasonExactPinOnly
147		}
148		if !eligibility.AutoRoutable {
149			if eligibility.Power <= 0 {
150				return fmt.Sprintf("model %q has no catalog power metadata", model), FilterReasonPowerMissing
151			}
152			return fmt.Sprintf("model %q is not auto-routable", model), FilterReasonNotAutoRoutable
153		}
154		return "", FilterReasonEligible
155	}
156	
157	// resolveRequestReasoning returns a copy of req with Reasoning resolved to the
158	// catalog's reasoning default for the request's policy/surface
159	// when the request asks for Reasoning=auto. This must run before CheckGating
160	// so candidates that only support a different reasoning level (e.g. an
161	// off-only variant under a policy whose surface default is "high") are
162	// correctly disqualified by the capability gate. Other Reasoning values
163	// (unset, off, named, numeric) are left untouched, preserving the existing
164	// behavior of those code paths.
165	func resolveRequestReasoning(req Request, surface string, resolver func(policy, surface string) (string, bool)) Request {
166		if resolver == nil || req.Policy == "" {
167			return req
168		}
169		policy, err := reasoning.ParseString(req.Reasoning)
170		if err != nil || policy.Kind != reasoning.KindAuto {
171			return req
172		}
173		resolved, ok := resolver(req.Policy, surface)
174		if !ok || resolved == "" {
175			return req
176		}
177		out := req
178		out.Reasoning = resolved
179		return out
180	}
