8	func TestPinPinConflictHarnessIncompatibleWithModel(t *testing.T) {
9		in := Inputs{Harnesses: []HarnessEntry{{
10			Name:                "claude",
11			Surface:             "claude",
12			CostClass:           "medium",
13			IsSubscription:      true,
14			AutoRoutingEligible: true,
15			Available:           true,
16			ExactPinSupport:     true,
17			SupportedModels:     []string{"opus-4.7"},
18			SupportsTools:       true,
19		}}}
20	
21		_, err := Resolve(Request{Harness: "claude", Model: "qwen3.6"}, in)
22		if err == nil {
23			t.Fatal("expected harness/model pin conflict")
24		}
25		var typed *ErrUnsatisfiablePin
26		if !errors.As(err, &typed) {
27			t.Fatalf("errors.As ErrUnsatisfiablePin: %T %v", err, err)
28		}
29		if typed.Pin != "harness=claude+model=qwen3.6" {
30			t.Fatalf("Pin=%q, want harness=claude+model=qwen3.6", typed.Pin)
31		}
32	}
